const width = 600;
const height = 600;

const svg = d3.select('#bubble-chart')
  .attr('width', width)
  .attr('height', height);

const tooltip = d3.select('body').append('div')
  .attr('class', 'tooltip');

function formatMarketCap(value) {
  if (!value || isNaN(value)) return 'N/A';
  if (value >= 1e12) return (value/1e12).toFixed(2) + 'T';
  if (value >= 1e9) return (value/1e9).toFixed(2) + 'B';
  if (value >= 1e6) return (value/1e6).toFixed(2) + 'M';
  return value.toFixed(2);
}

d3.csv('data/stock-descriptions.csv', d => ({
  ticker: d.ticker,
  sector: d.sector,
  name: d['full name'],
  marketCap: +d.marketCap,
  country: d.country,
  website: d.website
})).then(data => {
  const sectors = Array.from(new Set(data.map(d => d.sector)));
  const color = d3.scaleOrdinal()
    .domain(sectors)
    .range(d3.schemeTableau10.concat(d3.schemeSet3));

  const capValues = data.map(d => d.marketCap).filter(v => !isNaN(v) && v > 0);
  const radiusScale = d3.scaleSqrt()
    .domain([d3.min(capValues), d3.max(capValues)])
    .range([12, 45]);

  data.forEach(d => {
    d.radius = (!d.marketCap || isNaN(d.marketCap)) ? 15 : radiusScale(d.marketCap);
  });

  const clusterRadius = 170;
  const clusterCenters = {};
  sectors.forEach((s, i) => {
    const angle = 2 * Math.PI * i / sectors.length;
    clusterCenters[s] = {
      x: width/2 + clusterRadius * Math.cos(angle),
      y: height/2 + clusterRadius * Math.sin(angle)
    };
  });

  const simulation = d3.forceSimulation(data)
    .force('x', d3.forceX(d => clusterCenters[d.sector].x).strength(0.12))
    .force('y', d3.forceY(d => clusterCenters[d.sector].y).strength(0.12))
    .force('collide', d3.forceCollide(d => d.radius + 2))
    .force('charge', d3.forceManyBody().strength(0.5))
    .alphaDecay(0.02);

  const node = svg.append('g')
    .selectAll('g')
    .data(data)
    .enter().append('g')
    .attr('class', 'node')
    .on('mouseover', (event, d) => {
      if (!d.marketCap || isNaN(d.marketCap)) return;
      tooltip.style('opacity', 1)
        .html(`<strong>${d.ticker}</strong><br/>${d.name}<br/>Sector: ${d.sector}`);
    })
    .on('mousemove', (event) => {
      tooltip.style('left', (event.pageX + 10) + 'px')
        .style('top', (event.pageY + 10) + 'px');
    })
    .on('mouseout', () => {
      tooltip.style('opacity', 0);
    })
    .on('click', (event, d) => {
      selectTicker(d.ticker);
    });

  node.append('circle')
    .attr('r', d => d.radius)
    .attr('fill', d => color(d.sector));

  node.append('text')
    .text(d => d.ticker);

  simulation.on('tick', () => {
    node.attr('transform', d => `translate(${d.x},${d.y})`);
  });

  // Legend
  const legend = d3.select('#legend')
    .selectAll('.legend-item')
    .data(sectors)
    .enter().append('div')
    .attr('class', 'legend-item');

  legend.append('div')
    .attr('class', 'legend-color')
    .style('background', d => color(d));

  legend.append('div')
    .text(d => d);

  // Table
  const tbody = d3.select('#stock-table tbody');
  const rows = tbody.selectAll('tr')
    .data(data)
    .enter().append('tr')
    .attr('class', 'data-row')
    .on('click', (event, d) => {
      selectTicker(d.ticker);
    });

  rows.append('td').text(d => d.ticker);
  rows.append('td').text(d => d.name);
  rows.append('td').text(d => d.sector);
  rows.append('td').text(d => formatMarketCap(d.marketCap));

  let selectedTicker = null;
  function selectTicker(ticker) {
    selectedTicker = ticker;
    node.classed('selected', d => d.ticker === selectedTicker);
    rows.classed('selected', d => d.ticker === selectedTicker);
  }
});
